"""Create a factual model report from locked, completed evaluation artifacts."""
from common import *
def main():
    evaluation=json.loads((OUT/'reserved_evaluation_report.json').read_text());registry=json.loads((OUT/'final_model_registry.json').read_text());plan=json.loads((OUT/'final_training_locked_plan.json').read_text());development=json.loads((OUT/'development_comparison.json').read_text());project=json.loads((OUT/'project_final_prediction_receipt.json').read_text());assert evaluation['signature']['registry_sha256']==sha(OUT/'final_model_registry.json')==project['registry_sha256'];assert project['output_sha256']==sha(OUT/'project_final_model_predictions.csv');roles=registry['role_model_names'];rows=[]
    for study,rr in evaluation['results'].items():
        for stratum,result in rr['strata'].items():
            for model,m in result['point_metrics'].items():
                ci=result['primary_1Mb_block_bootstrap']['models'][model];rows.append({'study':study,'evidence_status':rr['evidence_status'],'stratum':stratum,'model':model,'n':m['n'],'detected_calls':m['detected_calls'],'call_rate':m['prevalence'],'AUROC':m['auroc'],'AUROC_CI95_low':ci['auroc_CI95'][0],'AUROC_CI95_high':ci['auroc_CI95'][1],'average_precision':m['average_precision'],'AP_CI95_low':ci['AP_CI95'][0],'AP_CI95_high':ci['AP_CI95'][1],'AP_skill_over_prevalence':m['AP_skill_over_prevalence'],'probabilities_are_calibrated':False})
    table=OUT/'final_evaluation_metrics.csv'
    with table.open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
    lines=['SLEEP–FRAILTY MOLECULAR AI MODEL','', 'What was built','A trained research model that ranks DNA changes for laboratory follow-up. It predicts source-specific DNA activity/effect readouts in two neural lab settings. It does not predict whether a person develops insomnia or frailty.','','What was actually trained','The final neural heads and context/variant networks were trained by backpropagation. The source tiny HyenaDNA encoder and HOCOMOCO DNA-binding patterns stay fixed in these final versions. Small conditional combination models learn coefficients and training-only score references. AlphaGenome itself was not fine-tuned. Only the designated permissible downloadable AVI scores were used.','','How the model was chosen',f'{len(development["aggregate"])} finite model families were compared over three development chromosome splits, with separate results for both studies. Neural candidates use fixed three-seed means. The strongest detector and strongest within-active variant ranker were chosen by the written development criteria. Final neural epochs were fixed from the development folds before refitting on all development chromosomes 4–22.', 'These folds were used for optimization, early stopping and selection. The conditional combination layer also has cross-fold base-fitting dependencies. These are not unbiased nested-CV estimates. The separate reserved evaluation is the performance check.','','Selected roles']
    for role in ['overall_assay_call_detector','within_active_variant_ranker']:lines.append(role+': '+roles[role])
    lines+=['','Reserved evaluation','Siraj: the fixed original library on chromosomes 1–3, with 355 additional rows close to previously analyzed Salomon/Retallick regions excluded before prediction. The strict set has 18,569 DNA changes. Original full-set results remain in the machine-readable report.','Salomon: previously used project study data; its chromosome1–3 result is not a new independent-study replication.','No reserved result was used to refit or reselect these models.']
    for study in STUDIES:
        lines+=['',study]
        for stratum,role in [('all_calls','overall_assay_call_detector'),('measured_active_regions','within_active_variant_ranker')]:
            name=roles[role];m=evaluation['results'][study]['strata'][stratum]['point_metrics'][name];ci=evaluation['results'][study]['strata'][stratum]['primary_1Mb_block_bootstrap']['models'][name];lines.append(f'  {stratum}: n={m["n"]:,}; detected calls={m["detected_calls"]:,}; call rate={m["prevalence"]:.4f}; AUROC={m["auroc"]:.4f} (95% CI {ci["auroc_CI95"][0]:.4f}–{ci["auroc_CI95"][1]:.4f}); average precision={m["average_precision"]:.4f} (95% CI {ci["AP_CI95"][0]:.4f}–{ci["AP_CI95"][1]:.4f}).')
    comparisons=[]
    for study in STUDIES:
        for stratum,role,comparator_roles in [('all_calls','overall_assay_call_detector',['ablation_motif_chromatin_no_avi']),('measured_active_regions','within_active_variant_ranker',['ablation_contrast_no_avi','combination_conditional_avi_only'])]:
            selected=roles[role];result=evaluation['results'][study]['strata'][stratum]
            for comparator_role in comparator_roles:
                other=roles[comparator_role];a=result['point_metrics'][selected];b=result['point_metrics'][other];ci=result['primary_1Mb_block_bootstrap']['paired_differences'][selected][other];comparisons.append({'study':study,'stratum':stratum,'selected_model':selected,'comparator':other,'selected_AP':a['average_precision'],'comparator_AP':b['average_precision'],'AP_difference':a['average_precision']-b['average_precision'],'AP_difference_CI95_low':ci['paired_AP_difference_CI95'][0],'AP_difference_CI95_high':ci['paired_AP_difference_CI95'][1],'AUROC_difference':a['auroc']-b['auroc'],'AUROC_difference_CI95_low':ci['paired_auroc_difference_CI95'][0],'AUROC_difference_CI95_high':ci['paired_auroc_difference_CI95'][1],'interpretation':'Positive nominal paired AP interval' if ci['paired_AP_difference_CI95'][0]>0 else 'AP difference uncertain at this nominal interval'})
    matched=OUT/'alphagenome_matched_comparisons.csv'
    with matched.open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(comparisons[0]));w.writeheader();w.writerows(comparisons)
    lines+=['','Observed matched comparisons (average precision; see CSV for paired intervals)']
    for r in comparisons:lines.append(f"  {r['study']} / {r['stratum']}: selected={r['selected_AP']:.4f}, comparator={r['comparator_AP']:.4f}; difference={r['AP_difference']:+.4f},95% interval {r['AP_difference_CI95_low']:+.4f}to{r['AP_difference_CI95_high']:+.4f}. {r['interpretation']}. Comparator: {r['comparator']}")
    lines+=['','Did AlphaGenome help?','Compare matched models and the AVI-only references in final_evaluation_metrics.csv and the paired differences in reserved_evaluation_report.json. A higher score in one selected result alone does not establish that AlphaGenome caused an improvement. The main detector compares with its matching no-AVI model; the conditional ranker compares with its DNA-only expert and the conditional AVI-only classifier. All tested versions and disagreements are retained.','The motif activity+AVI auxiliary family also drops the absolute-effect auxiliary target, so its contrast with activity+effect does not isolate AVI alone. The contrast-network teacher/no-teacher and detector input/no-input comparisons preserve the other targets and provide the cleaner ablations.', 'AUROC is a ranking measure, not percentage-correct accuracy. Average precision should be compared with the call rate. The genomic-block confidence intervals describe within-assay sampling uncertainty and are not adjusted for every reported comparison. A 5 Mb-block sensitivity is provided alongside the primary 1 Mb analysis.','','Project predictions',f'33 verified reference-to-alternate substitutions were scored in both study contexts. Every candidate has an exact audited AVI score. {project["rows"]} rows report model roles and flag exact or nearby training overlap. These are experiment-prioritization hypotheses. Candidate disease accuracy, causal genes and original risk-allele direction are not established. Do not compare raw scores between study contexts as a measure of cell-type relevance.','','What this does not establish','Patient insomnia/frailty prediction; independent participant genetic-score validation; genetic correlation; causation; causal-variant-to-gene mapping; age-related or single-cell mechanisms. The physical chromatin inputs are bulk neural proxies, including a neuroblastoma cell line and induced/fetal cell profiles. Nonsignificant assay rows are not proven biologically neutral. Foundation-genome training exposure has not been independently excluded. AVI scores refer to native GRCh38 contexts, which can differ from engineered reporter constructs.','','Reproduction and outputs','predict.py scores raw paired DNA plus caller-verified GRCh38 coordinates and an explicit studied assay context. It uses stored training transformations and does not require an AlphaGenome API key. It requires the hash-verified source model, motif and public-reference files and exact runtime versions. runtime_metadata.json describes the tested macOS ARM environment; a fresh installation or a different operating system is not yet validated.','The source/exclusion audits, locked plans, trained checkpoints, numerical/raw-input checks, independent R metric checks, full held-out predictions, model comparisons and project predictions remain available. The original GWAS and NHANES analyses were not used as target evidence for this model.']
    target=OUT/'MODEL_REPORT.txt';target.write_text('\n'.join(lines)+'\n');card=json.loads((OUT/'model_card_draft.json').read_text());card['implementation_checks']=[f"Final{json.loads((OUT/'final_fit_verification.json').read_text())['models_checked']}checkpoint/ensemble records checked on development raw-input examples with file hashes, independent CPU/GPU neural arithmetic and conditional-combiner batch/serialization/coefficient checks",f"{len(development['R_replays'])}independent R AUROC/AP development replays passed",f"{len(evaluation['independent_R_checks'])}independent R AUROC/AP reserved-evaluation replays passed",'Weighted/tied metric and paired genomic-block bootstrap arithmetic checked against scikit-learn'];card['updated_utc']=evaluation['completed_utc'];card.update({'status':'Training, locked evaluation and project molecular predictions complete; see measured performance and limitations','selected_role_names':{r:roles[r] for r in ['overall_assay_call_detector','within_active_variant_ranker']},'final_registry_sha256':sha(OUT/'final_model_registry.json'),'reserved_report_sha256':sha(OUT/'reserved_evaluation_report.json'),'strict_reserved_exposure_audit_sha256':sha(OUT/'reserved_exposure_audit.json'),'project_prediction_receipt':project,'blind_test_evaluated':True,'model_family_count_compared':len(development['aggregate']),'development_R_metric_replays':len(development['R_replays']),'reserved_R_metric_replays':len(evaluation['independent_R_checks']),'statistical_caution':'Block intervals are descriptive within-assay uncertainty and not adjusted for all comparisons. No independent participant/donor, clinical, causal or original-risk-direction validation.','conditional_stacking_qualification':development.get('stacking_qualification')});(OUT/'model_card.json').write_text(json.dumps(card,indent=2)+'\n');(OUT/'final_report_receipt.json').write_text(json.dumps({'registry_sha256':sha(OUT/'final_model_registry.json'),'reserved_report_sha256':sha(OUT/'reserved_evaluation_report.json'),'model_card_sha256':sha(OUT/'model_card.json'),'text_report_sha256':sha(target),'metrics_table_sha256':sha(table),'project_predictions_sha256':sha(OUT/'project_final_model_predictions.csv')},indent=2)+'\n');print('Wrote final model report/card and metric table',flush=True)
if __name__=='__main__':main()
